def is_colorful(m, n):
    flavors = list(range(n))
    coloring = [None] * m
    def solve(idx):
        if idx == m:
            for j in range(m):
                window = [coloring[(j + k) % m] for k in range(n + 1)]
                if len(set(window)) < n: return False
            return True
        for f in flavors:
            coloring[idx] = f
            if idx >= n:
                if len(set(coloring[idx-n : idx+1])) < n: continue
            if solve(idx + 1): return True
        return False
    return solve(0)

for m in range(5, 15):
    print(f"n=4, m={m}: {is_colorful(m, 4)}")

